// Prepare an output buffer per requirements: if size == 0, str may be NULL; otherwise str must be a writable buffer of at least size bytes.
unsigned int raw_sz = *FUZZ_PARAM(unsigned int);
size_t size = (size_t)(raw_sz % 2048); // keep allocations small per fuzzer guidance
std::string buf; // backing storage when size > 0
char *str = nullptr;
if (size > 0) {
    buf.assign(size, '\0');
    str = &buf[0]; // writable buffer
}

// Generate auxiliary argument values we may need for various format cases
int v_int = (int)(*FUZZ_PARAM(unsigned int));
unsigned int v_uint = *FUZZ_PARAM(unsigned int);
long v_long = (long)(*FUZZ_PARAM(unsigned long));
unsigned long v_ulong = *FUZZ_PARAM(unsigned long);
long long v_ll = (long long)(*FUZZ_PARAM(unsigned long long));
unsigned long long v_ull = *FUZZ_PARAM(unsigned long long);
size_t v_size = (size_t)(*FUZZ_PARAM(unsigned long long));
std::string s_arg = FUZZ_PARAM_STR();
const char *cstr = s_arg.c_str(); // non-null, null-terminated
int v_char = (int)(*FUZZ_PARAM(unsigned int) & 0xFF); // %c expects an int convertible to unsigned char
const void *v_ptr = (const void *)cstr; // safe non-null pointer for %p

// Choose a safe, supported format string and provide matching variadic args.
// We avoid width/precision from arguments (like %*.*d) to keep argument matching simple and correct.
unsigned int which = *FUZZ_PARAM(unsigned int) % 6;
const char *fmt = nullptr;
int ret = 0;
if (which == 0) {
    // No conversions; literal only
    fmt = "Hello, world!";
    ret = uk_snprintf(str, size, fmt);
} else if (which == 1) {
    // Mixed basic integer types
    fmt = "%d %u %x %o";
    ret = uk_snprintf(str, size, fmt, v_int, v_uint, v_uint, v_uint);
} else if (which == 2) {
    // Wider integer and size types
    fmt = "%lld %llu %zu %ld %lu";
    ret = uk_snprintf(str, size, fmt, v_ll, v_ull, v_size, v_long, v_ulong);
} else if (which == 3) {
    // Strings, char, and pointer
    fmt = "%s %c %p";
    ret = uk_snprintf(str, size, fmt, cstr, v_char, v_ptr);
} else if (which == 4) {
    // Flags and field widths (constants in the format string)
    fmt = "%% %08x %-5d %+lld";
    ret = uk_snprintf(str, size, fmt, v_uint, v_int, v_ll);
} else {
    // Length modifiers that rely on default argument promotions being int for h/hh
    int v_hhd_src = (int)(*FUZZ_PARAM(unsigned int));
    int v_hd_src = (int)(*FUZZ_PARAM(unsigned int));
    fmt = "%#x %#o %hhd %hd";
    ret = uk_snprintf(str, size, fmt, v_uint, v_uint, v_hhd_src, v_hd_src);
}

// Post-call notes:
// - If ret >= size and size > 0, the output was truncated but must be NUL-terminated per spec.
// - If size == 0, str is NULL and no write occurs; ret still reflects the number of chars that would have been written.
// We do not assert on return value since negative values may indicate implementation-defined errors.
